        let n = name.unwrap();
        bytes.extend_from_slice(n);
        bytes.push(0);
    }
    if flg & 0x10 != 0 {
        let c = comment.unwrap();
        bytes.extend_from_slice(c);
        bytes.push(0);
    }
    bytes
